function initSubscriptionWhenFooterVisible() {
    var t = document.querySelector(".site-footer");
    t && new IntersectionObserver((t, e) => {
        t.forEach(t => {
            t.isIntersecting && (new SubscriptionManager, e.disconnect())
        })
    }, {
        rootMargin: "100px",
        threshold: .1
    }).observe(t)
}
document.addEventListener("DOMContentLoaded", initSubscriptionWhenFooterVisible);